SELECT EXISTS (
    SELECT 1 FROM loan_ledger
    WHERE customer_id = #{customerId}
      AND status = 'SUBMITTED'
)

SELECT EXISTS (
    SELECT 1 FROM loan_ledger
    WHERE customer_id = #{customerId}
      AND product_id  = #{productId}
      AND status      = 'ACTIVE'
      AND start_date >= DATE_SUB(CURDATE(), INTERVAL 60 DAY)
)
